def d_n(n):
    return n**3 + 4*n**2 + 6*n + 4

def is_power_of_2(k):
    return k > 0 and (k & (k - 1) == 0)

def is_power_of_5(k):
    if k <= 0:
        return False
    while k % 5 == 0:
        k //= 5
    return k == 1

print("--- Investigation for D(n) = 2^k (n > 0) ---")
found_2k = []
for n in range(1, 16):
    d = d_n(n)
    if is_power_of_2(d):
        found_2k.append((n, d))
    print(f"n={n}: D(n)={d} is power of 2? {is_power_of_2(d)}")

print("\n--- Investigation for D(n) = 5^k (n > 0) ---")
found_5k = []
for n in range(1, 16):
    d = d_n(n)
    if is_power_of_5(d):
        found_5k.append((n, d))
    print(f"n={n}: D(n)={d} is power of 5? {is_power_of_5(d)}")

print("\nSummary for D(n) = 2^k:")
print(found_2k)
print("\nSummary for D(n) = 5^k:")
print(found_5k)
